#!/bin/sh
# Regenerate crates/melee/src/{mp,gr}/data.rs (stage collision and ground params).
set -eu
root=$(cd "$(dirname "$0")/.." && pwd)
src="$root/reference/melee/src"
rev=$(git -C "$root/reference/melee" rev-parse --short=12 HEAD)
gen() {
  out=$1; shift
  {
    printf '%s\n' "// @generated by tools/gen_stage_data.sh from doldecomp/melee $rev." \
      "// Do not edit by hand; regenerate." "" \
      "use crate::dat::{dat_struct, DatField, DatPtr};" \
      "#[allow(unused_imports)]" "use crate::math::{Vec2, Vec3};" ""
    python3 "$root/tools/gen_dat_structs.py" "$src/melee" "$src/sysdolphin" -- "$@"
  } > "$out"
}
gen "$root/crates/melee/src/mp/data.rs" MapCollData MapLine MapJoint MapLineRange
gen "$root/crates/melee/src/gr/data.rs" GroundParam
